---@class WorldBossInitDojo
local WorldBossInitDojo = Class("WorldBossInitDojo")

function WorldBossInitDojo:__init()
    self.historyMaxHurt = 0
    self.hurtDrawRewardId = {}
    self.worldBossLastRankInfo = {}
end

function WorldBossInitDojo:__delete()
    self.historyMaxHurt = nil
    self.hurtDrawRewardId = nil
    self.worldBossLastRankInfo = nil
end

---Update
---更新数据
---@param jsonData table
function WorldBossInitDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
        end
    end
end

function WorldBossInitDojo:AddDrawId(id)
    if not id then
        return
    end
    table.insert(self.hurtDrawRewardId, checkString(id))
end

function WorldBossInitDojo:OneKeyDraw()
    local alreadyDrawIdsHash = {}
    for _, id in ipairs(self.hurtDrawRewardId) do
        alreadyDrawIdsHash[checkString(id)] = true
    end
    -- 所有奖励
    local allRewardsVo = CfUtils.GetCf(AutoIds.IdSetting976, "WorldBossHurtRewardVo", true)
    for _, reward in ipairs(allRewardsVo) do
        ---@type WorldBossHurtRewardVo
        local rewardVo = reward
        if self.historyMaxHurt >= checkNumber(rewardVo.upperLimit) then
            if not checkBool(alreadyDrawIdsHash[rewardVo.id]) then
                self:AddDrawId(rewardVo.id)
            end
        end
    end
end

function WorldBossInitDojo:IsHaveDraw(rewardId)
    local alreadyDrawIdsHash = {}
    for _, id in ipairs(self.hurtDrawRewardId) do
        alreadyDrawIdsHash[checkString(id)] = true
    end
    return checkBool(alreadyDrawIdsHash[checkString(rewardId)])
end

function WorldBossInitDojo:IsCanOneKeyDraw()
    local alreadyDrawIdsHash = {}
    for _, id in ipairs(self.hurtDrawRewardId) do
        alreadyDrawIdsHash[checkString(id)] = true
    end
    -- 所有奖励
    local allRewardsVo = CfUtils.GetCf(AutoIds.IdSetting976, "WorldBossHurtRewardVo", true)
    for _, reward in ipairs(allRewardsVo) do
        ---@type WorldBossHurtRewardVo
        local rewardVo = reward
        if self.historyMaxHurt >= checkNumber(rewardVo.upperLimit) then
            if not checkBool(alreadyDrawIdsHash[checkString(rewardVo.id)]) then
                return true
            end
        end
    end
    return false
end

return WorldBossInitDojo